# dotnet package list --format json outputs valid JSON
# Let's just grep for the key differences
import re

def extract_versions(content):
    results = {}
    # Find project/package pairs
    current_project = None
    for line in content.split('\n'):
        if '\"path\"' in line:
            m = re.search(r'\"path\"\s*:\s*\"([^\"]+)\"', line)
            if m:
                current_project = m.group(1).split('/')[-1].split('\\\\')[-1]
        if '\"id\"' in line:
            m = re.search(r'\"id\"\s*:\s*\"([^\"]+)\"', line)
            if m:
                pkg_id = m.group(1)
        if '\"resolvedVersion\"' in line:
            m = re.search(r'\"resolvedVersion\"\s*:\s*\"([^\"]+)\"', line)
            if m and current_project:
                results.setdefault(current_project, {})[pkg_id] = m.group(1)
    return results

baseline = extract_versions(content)
after = extract_versions(after_content)

print('=== CHANGES ===')
for proj in sorted(set(list(baseline.keys()) + list(after.keys()))):
